  "packages/core/src/models/errors.ts": "export class ContextOSError extends Error {\n  constructor(message: string) {\n    super(message);\n    this.name = 'ContextOSError';\n    Object.setPrototypeOf(this, new.target.prototype);\n  }\n}\n\nexport class ValidationError extends ContextOSError {\n  public readonly issues: unknown[];\n\n  constructor(message: string, issues: unknown[] = []) {\n    super(message);\n    this.name = 'ValidationError';\n    this.issues = issues;\n  }\n}\n\nexport class EntityNotFoundError extends ContextOSError {\n  public readonly entityType: string;\n  public readonly id: string;\n\n  constructor(entityType: string, id: string) {\n    super(`${entityType} with ID '${id}' was not found.`);\n    this.name = 'EntityNotFoundError';\n    this.entityType = entityType;\n    this.id = id;\n  }\n}\n\nexport class CycleDetectedError extends ContextOSError {\n  public readonly fromId: string;\n  public readonly toId: string;\n\n  constructor(fromId: string, toId: string) {\n    super(`Cycle detected in decision supersession DAG: '${toId}' cannot supersede '${fromId}'.`);\n    this.name = 'CycleDetectedError';\n    this.fromId = fromId;\n    this.toId = toId;\n  }\n}\n",
  "packages/core/src/models/project.ts": "import { z } from 'zod';\n\nexport const ProjectSchema = z.object({\n  id: z.string().uuid(),\n  name: z.string().min(1, 'Project name is required'),\n  rootPath: z.string().min(1, 'Project root path is required'),\n  createdAt: z.string().datetime().default(() => new Date().toISOString()),\n});\n\nexport type Project = z.infer<typeof ProjectSchema>;\n\nexport const CreateProjectInputSchema = ProjectSchema.omit({\n  id: true,\n  createdAt: true,\n}).extend({\n  id: z.string().uuid().optional(),\n});\n\nexport type CreateProjectInput = z.infer<typeof CreateProjectInputSchema>;\n",
